  height: 4px;
  background: #ffd700;
  display: inline-block;
}

/* Chassis Right Info & Button */
.sgs-chassis-right {
  display: flex;
  align-items: center;
  gap: 12px;
}
.sgs-speed-pill-box {
  background: #090e17;
  border: 1px solid #1a253a;
  border-radius: 5px;
  padding: 6px 10px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.sgs-speed-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-family: monospace;
}
.sgs-dir-icon.in { color: #00e676; font-weight: 700; }
.sgs-dir-icon.out { color: #38bdf8; font-weight: 700; }
.sgs-speed-val { color: #f8fafc; font-weight: 700; }
.sgs-btn-info {
  background: #131b2e;
  border: 1px solid #25334d;
  color: #38bdf8;
  font-size: 10.5px;
  font-weight: 700;
  padding: 8px 12px;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.2s ease;
}
.sgs-btn-info:hover {
