  font-weight: 800;
  color: #f8fafc;
  letter-spacing: -0.5px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", monospace;
}
.sgs-kpi-in .sgs-kpi-val { color: #00e676; }
.sgs-kpi-out .sgs-kpi-val { color: #38bdf8; }
.sgs-kpi-sub {
